import{_ as a,c as i,o,aj as t}from"./chunks/framework.D4QnD388.js";const u=JSON.parse('{"title":"About ArXiv Radar","description":"","frontmatter":{},"headers":[],"relativePath":"arxiv/about.md","filePath":"arxiv/about.md"}'),r={name:"arxiv/about.md"};function d(n,e,s,l,c,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="about-arxiv-radar" tabindex="-1">About ArXiv Radar <a class="header-anchor" href="#about-arxiv-radar" aria-label="Permalink to &quot;About ArXiv Radar&quot;">​</a></h1><h2 id="purpose-and-editorial-scope" tabindex="-1">Purpose and editorial scope <a class="header-anchor" href="#purpose-and-editorial-scope" aria-label="Permalink to &quot;Purpose and editorial scope&quot;">​</a></h2><p>ArXiv Radar is an educational discovery tool, not an investment-research recommendation engine. It helps readers find recent work at the intersection of AI, LLM and agent systems with finance and quantitative research. Each paper should be evaluated through its original arXiv record, methods, data and limitations.</p><p>This subsection is a focused arXiv monitoring stack for the overlap of:</p><ul><li>AI / LLM / agent systems</li><li>finance applications and quantitative research workflows</li><li>agent planning, deep research, multi-agent coordination, tool use, reasoning, and memory</li></ul><h2 id="what-the-pipeline-does" tabindex="-1">What the pipeline does <a class="header-anchor" href="#what-the-pipeline-does" aria-label="Permalink to &quot;What the pipeline does&quot;">​</a></h2><ol><li>Pulls recent papers from 10 monitored arXiv categories.</li><li>Uses DashScope / Qwen to assign research tags, extract keywords, and generate Chinese summaries.</li><li>Normalizes affiliations, computes trend statistics, generates embeddings, and publishes static JSON.</li><li>Powers a VitePress browsing experience under <code>/arxiv/</code>.</li></ol><h2 id="update-policy-and-provenance" tabindex="-1">Update policy and provenance <a class="header-anchor" href="#update-policy-and-provenance" aria-label="Permalink to &quot;Update policy and provenance&quot;">​</a></h2><p>The automated pipeline runs daily. The displayed tags, summaries and affiliations are machine-generated navigation aids and may contain errors. The primary source for every research claim is the original arXiv paper linked in the Radar; the site reports when the generated dataset was last updated.</p><h2 id="monitored-categories" tabindex="-1">Monitored categories <a class="header-anchor" href="#monitored-categories" aria-label="Permalink to &quot;Monitored categories&quot;">​</a></h2><ul><li><code>cs.AI</code></li><li><code>cs.CL</code></li><li><code>cs.MA</code></li><li><code>cs.IR</code></li><li><code>cs.SE</code></li><li><code>cs.CE</code></li><li><code>q-fin.ST</code></li><li><code>q-fin.CP</code></li><li><code>q-fin.PM</code></li><li><code>q-fin.TR</code></li></ul><h2 id="main-research-tags" tabindex="-1">Main research tags <a class="header-anchor" href="#main-research-tags" aria-label="Permalink to &quot;Main research tags&quot;">​</a></h2><ul><li><code>ai-finance</code></li><li><code>agent-planning</code></li><li><code>deep-research</code></li><li><code>multi-agent</code></li><li><code>tool-use</code></li><li><code>reasoning</code></li><li><code>memory</code></li><li><code>rag</code></li><li><code>time-series</code></li></ul><h2 id="output-locations" tabindex="-1">Output locations <a class="header-anchor" href="#output-locations" aria-label="Permalink to &quot;Output locations&quot;">​</a></h2><ul><li>Raw generated data: <code>data/papers.json</code>, <code>data/stats.json</code>, <code>data/embeddings_index.json</code></li><li>Public site data: <code>docs/public/arxiv-data/</code></li><li>Public chart assets: <code>docs/public/arxiv-charts/</code></li><li>Pipeline code: <code>scripts/arxiv_radar/</code></li></ul>',15)])])}const m=a(r,[["render",d]]);export{u as __pageData,m as default};
